std::vector<BuildingEvidenceRecord> build_evidence_records()
{
	std::vector<BuildingEvidenceRecord> records;
	records.reserve(3);
	records.emplace_back(BuildingEvidenceId("Evidence.SpatialManifest"), BuildingEvidenceKind::GeneratedManifest, BuildingEvidenceAuthority::Authoritative, "examples/SMB_OMv2_Instance_SMB_001/SMB_OMv2_Spatial_Object_Model.json", "Accepted SMB-OMv2 spatial object manifest.", 0);
	records.emplace_back(BuildingEvidenceId("Evidence.SmbOmv2RuntimeAcceptance"), BuildingEvidenceKind::CompatibilityGate, BuildingEvidenceAuthority::Authoritative, "tests/evidence/smb_omv2_acceptance_2026-08-21.json", "Accepted SMB-OMv2 runtime and priority-validity evidence.", 0);
	records.emplace_back(BuildingEvidenceId("Evidence.Omv21Authoring"), BuildingEvidenceKind::AuthoredSource, BuildingEvidenceAuthority::Authoritative, "SMB-OMv2.1 authoring modules", "Reviewed SMB-OMv2.1 catalogs, functions, services, requirements, and scenarios.", 0);
	return records;
}

