std::vector<BuildingScenario> build_scenarios()
{
	std::vector<BuildingScenario> records;
	records.reserve(11);
	records.emplace_back(BuildingScenarioId("Scenario.AuthoredConfiguration"), "AuthoredConfiguration", "Inspect the accepted authored configuration.");
	records.emplace_back(BuildingScenarioId("Scenario.ResolvedPlacement"), "ResolvedPlacement", "Inspect deterministic SMB-OMv2 resolved placement.");
	records.emplace_back(BuildingScenarioId("Scenario.NormalOccupancy"), "NormalOccupancy", "Represent normal discrete occupancy availability.");
	records.emplace_back(BuildingScenarioId("Scenario.BuildingUnoccupied"), "BuildingUnoccupied", "Represent an unoccupied building state.");
	records.emplace_back(BuildingScenarioId("Scenario.ElectricalPowerUnavailable"), "ElectricalPowerUnavailable", "Represent unavailable electrical service.");
	records.emplace_back(BuildingScenarioId("Scenario.ColdWaterUnavailable"), "ColdWaterUnavailable", "Represent unavailable cold-water service.");
	records.emplace_back(BuildingScenarioId("Scenario.HotWaterUnavailable"), "HotWaterUnavailable", "Represent unavailable hot-water service.");
	records.emplace_back(BuildingScenarioId("Scenario.HVACUnavailable"), "HVACUnavailable", "Represent unavailable HVAC service.");
	records.emplace_back(BuildingScenarioId("Scenario.SmokeDetectedGroundFloor"), "SmokeDetectedGroundFloor", "Represent a ground-floor smoke-monitoring event.");
	records.emplace_back(BuildingScenarioId("Scenario.SmokeDetectedUpperFloor"), "SmokeDetectedUpperFloor", "Represent an upper-floor smoke-monitoring event.");
	records.emplace_back(BuildingScenarioId("Scenario.MaintenanceInspection"), "MaintenanceInspection", "Represent deterministic maintenance inspection state.");
	return records;
}

